// Görüntü, Ses ve Video Üretimi cheat sheet. 9 konu.
import type { Topic } from './types'

export const medyaGiris: { q: string; a: string }[] = [
  { q: 'Bu başlık ne öğretir?', a: 'Metin dışındaki üretken yapay zekayı: görsel üreten araçlar (Midjourney, DALL-E, Stable Diffusion, Flux), ses (metinden konuşma, konuşmadan metin, müzik), video ve bunları iş akışına bağlamayı. Hem tarayıcıdan kullanım hem bilgisayarında ücretsiz çalıştırma hem de kodla otomasyon var.' },
  { q: 'Bu araçlar nasıl görsel üretiyor?', a: 'Çoğu "diffusion" (yayılım) denen yöntemle: tamamen rastgele bir gürültüden başlar, senin yazdığın metne bakarak gürültüyü 20-30 adımda temizler ve bir görsel ortaya çıkar. Eğitimde milyonlarca görsele gürültü ekleyip geri almayı öğrenmiştir. Ses ve video modelleri benzer fikri zaman boyutuna taşır. Temeller bölümünde ayrıntı var.' },
  { q: 'Hangi aracı kullanmalıyım?', a: 'Hızlı ve estetik sonuç için Midjourney; metin anlayan, düzenleme yapan ve görsel içine yazı yazabilen için ChatGPT (GPT Image) ve Gemini; tam kontrol, ücretsiz ve gizli için bilgisayarında Stable Diffusion ya da Flux. Profesyoneller birkaçını birlikte kullanır: konsept birinde, düzeltme diğerinde.' },
  { q: 'Bilgisayarımda çalıştırmak için ne gerekir?', a: 'Bulut araçlar için hiçbir şey. Yerel Stable Diffusion için 8-12 GB bellekli bir NVIDIA ekran kartı (SDXL), Flux için 16 GB ve üstü. Mac\'in M serisi çipleri çalışır ama yavaştır. Ekran kartın yoksa RunPod gibi saatlik GPU kiralama servisleri ya da Colab var.' },
  { q: 'Görsel promptu metin promptundan farklı mı?', a: 'Evet. Dil modeline cümle yazarsın; görsel modele kısa, somut, virgülle ayrılmış ve çoğunlukla İngilizce anahtar kelimeler: konu, ortam, stil, ışık, kamera. İstemediklerini de ayrı bir listeyle söylersin (negatif prompt). Prompt Mühendisliği\'nin medya konusu temeli verdi; burada derinleşiyor.' },
  { q: 'ComfyUI, ControlNet, LoRA gibi kelimeler ne?', a: 'ComfyUI: Stable Diffusion\'ı düğümleri bağlayarak kullandığın yerel arayüz; en güçlü ve esnek olanı. ControlNet: bir çizim ya da poz verip görselin ona uymasını sağlayan kontrol aracı. LoRA: modele kendi stilini ya da karakterini öğreten küçük ek dosya. Hepsi bu bölümde kendi konusunda anlatılıyor.' },
  { q: 'Ürettiğim görseli ticari olarak kullanabilir miyim?', a: 'Araca ve ülkeye bağlı. Her aracın kendi şartları var (Midjourney ücretli planda ticari hak verir); yapay zeka üretiminin telifi ülkeden ülkeye belirsiz; gerçek kişi yüzü ve marka logosu ayrı kurallara tabi. Kurumsal işlerde Adobe Firefly gibi "telif temiz" seçenekler var. Etik konusu bunları işler.' },
  { q: 'Ses tarafında neler var?', a: 'Üç iş: yazıyı doğal sesle okutmak (TTS; ElevenLabs, OpenAI, yerel Piper), konuşmayı yazıya dökmek (STT; Whisper), müzik üretmek (Suno, MusicGen). Ses klonlama 30 saniyelik örnekten mümkün ama yalnızca izinli seslerde. Sesli asistan bu parçaların dil modeliyle birleşimidir.' },
  { q: 'Video üretimi ne durumda?', a: 'En yeni ve en hızlı gelişen alan: Sora, Veo, Runway, Kling metinden ya da görselden 5-10 saniyelik klipler üretir. Tutarlılık, eller ve fizik hâlâ zayıf; uzun video kısa kliplerin kurguyla birleştirilmesidir. Görselden video üretmek metinden üretmekten daha kontrollüdür.' },
  { q: 'Ön koşul ne?', a: 'Prompt Mühendisliği (medya promptları konusu). Kod kısımları için LLM API başlığı; bilgisayarında çalıştırmak için biraz kurulum sabrı. Fine-tuning başlığındaki diffusion LoRA konusu, kendi stilini öğretmek istersen gerekir.' },
  { q: 'Hangi sırayla ilerlemeli?', a: 'Soldaki sıra: Görsel Araçlar → Görsel Prompt → Yerel ComfyUI → Kontrol Araçları → Kodla Görsel → Ses → Video → İş Akışları → Etik. İlk iki konu ile bulut araçlarda iyi sonuç alırsın; yerel ve kontrol konuları profesyonel işler için.' },
]

